function resolveParentMerge(agentJson, agentPath, depth) {
    depth = depth || 0;
    var childParams = (agentJson && agentJson.params) ? agentJson.params : {};

    if (!agentJson || !agentJson.parent || !agentJson.parent.path || depth > 10) {
